// Get the raw response from OpenAI
const rawResponse = $input.first().json.output[0].content[0].text

// Clean up the response (remove any markdown code blocks if present)
let cleanedResponse = rawResponse.trim();
cleanedResponse = cleanedResponse.replace(/```json\n?/g, '');
cleanedResponse = cleanedResponse.replace(/```\n?/g, '');

// Parse JSON
let imageAnalysis;
try {
  imageAnalysis = JSON.parse(cleanedResponse);
} catch (error) {
  // If parsing fails, return default (no images)
  console.error('Failed to parse JSON:', error);
  imageAnalysis = {
    imageCount: 0,
    reasoning: "Failed to parse image analysis",
    images: []
  };
}

// Get the LinkedIn post from the previous "Message a model" node
const linkedinPost = $('Message a model').item.json.output[0].content[0].text;

// Get newsletter metadata from Gmail Trigger
const newsletterSubject = $('Gmail Trigger - Newsletter Monitor').item.json.subject;

// Format current date/time
const now = new Date();
const newsletterDate = now.getFullYear() + '-' + 
  String(now.getMonth() + 1).padStart(2, '0') + '-' + 
  String(now.getDate()).padStart(2, '0') + ' ' + 
  String(now.getHours()).padStart(2, '0') + ':' + 
  String(now.getMinutes()).padStart(2, '0');

// Return the parsed data
return {
  json: {
    imageCount: imageAnalysis.imageCount || 0,
    reasoning: imageAnalysis.reasoning || "",
    images: imageAnalysis.images || [],
    linkedinPost: linkedinPost,
    newsletterSubject: newsletterSubject,
    newsletterDate: newsletterDate
  }
};
